	// AddAllowedPublishingKey adds a publishing key allowed to publish an artifact.
	AddAllowedPublishingKey(context.Context, *connect.Request[hub.AddAllowedPublishingKeyRequest]) (*connect.Response[hub.AddAllowedPublishingKeyResponse], error)
